// Original teaching notes. References are further reading, not copied article text.
const chapter = (id: string, title: string, keywords: string, paragraphs: string[], equation: string, example: string[], pitfalls: string[], question: string, answer: string, references: string[] = ["mit"]): Chapter => ({ id, title, keywords, paragraphs, equation, example, pitfalls, question, answer, references });
export const CHAPTERS: Chapter[] = [
chapter("numbers", "Bits, place value, and representation", "binary hexadecimal octal base conversion unsigned bit", [
  "A bit distinguishes two states. A word is an ordered group of bits; a representation assigns meaning to that pattern. The pattern 1111 can mean unsigned fifteen, signed minus one, an instruction field, or four independent flags. Hardware stores the pattern; the operation and format determine its interpretation.",
  "In a positional base-b system, the digit at position i contributes digit × bⁱ. Binary uses powers of two. Hexadecimal groups four binary digits into one symbol, making addresses and masks easier to read without changing the stored value. Leading zeroes preserve width but do not change an unsigned value.",
  "Convert an integer to another base by repeated division: each remainder is the next digit from right to left. Convert a fraction by repeated multiplication: each integer part supplies the next digit after the point. Some finite decimal fractions repeat indefinitely in binary, so finite storage requires rounding."
], "Unsigned n-bit range: 0 ≤ x ≤ 2ⁿ − 1; value = Σ bᵢ2ⁱ", ["For 101101₂, retain the weights 32, 8, 4, and 1.", "Add them: 32 + 8 + 4 + 1 = 45₁₀.", "Group from the right: 0010 1101₂ = 2D₁₆. Both representations describe the same value."], ["A hexadecimal digit occupies four bits, not four bytes.", "Bit width and numeric value are different properties."], "How many distinct patterns fit in 6 bits, and what is the largest unsigned value?", "There are 2⁶ = 64 patterns. Counting starts at zero, so the maximum is 63."),
chapter("signed", "Signed arithmetic and overflow", "signed complement magnitude overflow carry subtraction", [
  "Two’s complement gives the most significant bit weight −2ⁿ⁻¹ and keeps the other weights positive. This creates one zero and a negative range with one extra value. An adder can perform both unsigned and signed addition because both use arithmetic modulo 2ⁿ; the interpretation of overflow differs.",
  "Negate a value by inverting every bit and adding one within the chosen width. Subtraction A − B becomes A + complement(B) + 1. Carry-out reports an unsigned event. Signed overflow means the true signed answer lies outside the representable range: equal-sign inputs produced an opposite-sign result.",
  "When widening a signed value, replicate the sign bit. Zero-extension is correct for unsigned values. Truncation can destroy either interpretation. The most negative two’s-complement value has no positive counterpart of the same width, so negating it overflows."
], "n-bit signed range: −2ⁿ⁻¹ … 2ⁿ⁻¹ − 1; V = carry into sign bit XOR carry out", ["Use 4 bits: 7 is 0111 and 3 is 0011.", "Addition produces 1010, with no carry-out. Interpreted as signed, it is −6.", "The exact result 10 exceeds +7: signed overflow occurred even though carry-out is zero."], ["Carry is not signed overflow.", "Complement and add one only after choosing a width."], "Why does 1111 become 11111111 when sign-extended?", "1111 represents −1 in four-bit two’s complement. Replicating its sign preserves −1 in eight bits; zero-extension would instead produce +15."),
chapter("floating", "Fixed point and floating point", "fixed point floating ieee fp32 fp16 bf16 precision quantization", [
  "Fixed point places an implicit binary point at a fixed position. The stored integer q represents q × 2⁻ᶠ when f fractional bits are used. This makes scaling predictable, but the designer must budget range and precision together. Multiplication changes the scale and normally needs a wider intermediate.",
  "Floating point separates sign, exponent, and significand. The exponent moves the effective point, giving a wide dynamic range. Normal binary32 uses one sign bit, eight exponent bits with bias 127, and 23 explicit fraction bits with an implicit leading one. Subnormals use a different leading-bit rule; reserved exponents encode infinities and NaNs.",
  "Rounding selects a representable neighbor when an exact result is unavailable. Relative precision is approximately constant for normal values, while absolute spacing grows with magnitude. Arithmetic is not generally associative: changing addition order can change rounding. Quantized integer formats similarly trade precision for storage and bandwidth, using an explicit scale and sometimes a zero point."
], "Normal binary32: x = (−1)ˢ × (1 + f/2²³) × 2^(e−127); fixed point: x = q/2ᶠ", ["Represent 5.75: its binary expansion is 101.11₂ = 1.0111₂ × 2².", "Binary32 sign is 0; biased exponent is 129 = 10000001₂.", "Fraction begins 0111 followed by zeroes. The leading 1 is implicit for this normal value."], ["A larger exponent range does not imply more significant digits.", "NaN is not an ordinary large number; subnormals do not have an implicit leading one."], "With four fractional bits, what is the fixed-point spacing?", "Adjacent integer codes differ by 2⁻⁴ = 1/16 = 0.0625."),
chapter("codes", "Codes and error control", "gray bcd parity hamming crc error code syndrome", [
  "A code maps a set of messages to bit patterns. BCD assigns four bits to each decimal digit; Gray code arranges adjacent values to differ by one bit. Neither is a replacement for ordinary binary arithmetic. Gray code reduces ambiguity during position transitions, but it does not guarantee arbitrary errors can be corrected.",
  "Redundancy makes errors detectable. Even parity chooses a check bit so the total number of ones is even. It detects any odd number of flipped bits but misses every even-count flip pattern. Hamming distance is the number of differing positions between codewords. A minimum distance d detects up to d−1 errors or corrects up to floor((d−1)/2) errors under the assumed error model.",
  "Hamming codes place parity checks at power-of-two positions. Each check covers positions whose binary index has the corresponding bit set. The syndrome identifies a single erroneous position. Extended Hamming adds overall parity for single-error correction and double-error detection. CRC instead treats a bitstring as a polynomial over GF(2): XOR division by a generator produces a remainder used for detection, with guarantees depending on that generator."
], "Hamming check bits: 2ʳ ≥ m + r + 1; reflected binary Gray: g = b XOR (b >> 1)", ["For Hamming(7,4), parity bits occupy positions 1, 2, and 4; data occupies 3, 5, 6, and 7.", "If bit 5 flips, parity checks 1 and 4 fail while check 2 passes.", "The syndrome is 101₂ = 5. Flip position 5 to correct a single-bit error."], ["Basic Hamming(7,4) cannot reliably distinguish all double errors from single errors.", "A CRC detects corruption; it does not normally identify which bit to repair."], "Will one parity bit detect two simultaneous flips?", "No. Two flips preserve the parity of the total count of ones."),
chapter("boolean", "Boolean functions, laws, and truth tables", "boolean expression truth table demorgan absorption minterm maxterm sop pos", [
  "A Boolean function maps each input combination to zero or one. With n inputs there are 2ⁿ rows in its truth table. Expressions, tables, and gate networks are different representations of the same mapping. Establish the function first; choosing an economical implementation comes afterward.",
  "AND requires all operands to be one; OR requires at least one; NOT complements its operand. Boolean addition is OR, so 1 + 1 = 1. Identity, complement, distributive, and absorption laws let us transform expressions without changing the mapping. De Morgan’s laws exchange AND with OR when every operand and the overall result are complemented.",
  "A minterm includes every variable once and selects exactly one row. OR the minterms for rows whose output is one to obtain canonical SOP. A maxterm is zero for exactly one row; AND the maxterms for zero rows to obtain canonical POS. A simplified expression can omit variables within a term; canonical and minimum are different requirements."
], "(AB)′ = A′ + B′; (A + B)′ = A′B′; A + AB = A", ["Simplify F = AB + AB′.", "Factor A: F = A(B + B′). The complement law gives B + B′ = 1.", "Therefore F = A. Check all four input rows to verify equivalence."], ["OR is not integer addition, and XOR is not OR.", "A don’t-care is a specification freedom, not permission to change a required row."], "Why do A + AB and A agree for every input?", "If A = 1, both outputs are 1. If A = 0, AB is also 0, so both outputs are 0."),
chapter("gates", "From Boolean algebra to gate networks", "gate nand nor xor xnor buffer tri state fan combinational circuit", [
  "A logic gate implements a Boolean operation using physical voltages classified as logic levels. Its symbol describes function rather than transistor detail. NAND and NOR are universal: either family alone can implement any Boolean function. XOR is one for unequal inputs and is useful for parity and arithmetic.",
  "Combinational logic has outputs determined by present inputs once propagation has settled. Wire a network by tracing dependencies from sources to sinks. A legal gate network must avoid conflicting drivers. A tri-state output can enter high impedance so another device can drive a shared line; high impedance is different from logic zero.",
  "Real gates have propagation delay, capacitive loading, finite drive strength, and input thresholds. A change can take different paths to an output and create a temporary glitch even when the final Boolean answer is correct. Logical equivalence alone does not establish timing correctness."
], "XOR: A ⊕ B = A′B + AB′; NAND inverter: A′ = NAND(A, A)", ["Construct AND using only NAND gates.", "First form N = NAND(A,B) = (AB)′.", "Connect N to both inputs of a second NAND: NAND(N,N) = AB."], ["Never connect two ordinary output drivers together to compute OR.", "An unconnected input has no guaranteed logical value in a physical circuit."], "What changes when a tri-state buffer is disabled?", "Its output becomes high impedance. Other enabled hardware or a pull resistor determines the line voltage."),
chapter("kmap", "Karnaugh maps and exact minimization", "karnaugh k-map kmap implicant prime quine mccluskey minimization circuit compare", [
  "A Karnaugh map rearranges a truth table in Gray-code order. Horizontally or vertically adjacent cells differ in one variable, including opposite edges. Combining adjacent one-cells removes changing variables from a product term. Diagonal cells do not form a pair.",
  "For SOP, choose rectangular power-of-two groups containing only ones and optional don’t-cares. A group of 2ᵏ cells eliminates k variables. Groups may overlap and wrap. A prime implicant cannot be enlarged; an essential prime implicant covers a required minterm no other prime covers. Cover all required ones, not necessarily every don’t-care.",
  "Quine–McCluskey performs the same combination systematically using binary terms and dash positions. A prime implicant chart then solves the covering problem. Minimum term count, minimum literals, gate depth, and hazard-free implementation are different optimization objectives; an expression that is minimal under one cost may lose under another."
], "An n-variable group of 2ᵏ cells leaves n − k literals", ["For F(A,B,C) = Σm(1,3,5,7), mark all odd-numbered minterms.", "Their A and B values vary over all combinations; C stays one.", "The four-cell group therefore yields F = C."], ["Map order is 00, 01, 11, 10, not binary numeric order.", "A don’t-care may enlarge a group but is never a required one."], "Can two edge cells be adjacent?", "Yes. Opposite map edges wrap because their Gray labels differ in one bit."),
chapter("arithmetic", "Adders, subtraction, and ALU flags", "adder arithmetic alu carry half full lookahead ripple flag multiply booth wallace shifter", [
  "A half adder adds two one-bit operands; a full adder adds a carry-in as well. Chaining full adders produces an n-bit ripple adder. The sum is available only after the carry path settles. Carry-lookahead uses generate and propagate signals to shorten that dependency at the cost of more logic and wiring.",
  "An ALU combines arithmetic and logic functions behind an operation selector. Addition, subtraction, AND, OR, and shifts share operand ports and a result path. Status flags summarize a result: zero tests all result bits, negative reads the sign bit, carry describes unsigned arithmetic, and overflow describes signed range failure. Flag conventions for subtraction vary by ISA.",
  "Multiplication forms shifted partial products. An unsigned n-by-n product may require 2n bits. Compressor trees such as Wallace trees reduce many rows without propagating a carry across every row, leaving one final carry-propagate addition. Booth recoding treats runs of ones efficiently and supports signed multiplication when shifts and sign extension are correct."
], "Full adder: S = A ⊕ B ⊕ Cᵢₙ; Cₒᵤₜ = AB + ACᵢₙ + BCᵢₙ", ["Add 0101₂ and 0011₂ from right to left.", "Bit 0 produces sum 0, carry 1. The next columns propagate and generate carries.", "The result is 1000₂ = 8 unsigned. In signed four-bit arithmetic, +5 + +3 overflows to −8."], ["A logical right shift inserts zero; an arithmetic right shift replicates the sign.", "A correct low word does not prove that a wide product fits in the destination."], "Why can a ripple adder be slow even though every full adder works in parallel?", "Higher sums depend on carries generated by lower stages. The worst-case carry must traverse the chain."),
chapter("routing", "Selection, decoding, and encoding", "mux demux multiplexer decoder encoder seven segment codec routing priority encoder", [
  "A multiplexer selects one of several inputs and forwards it to one output. With k select bits it can select up to 2ᵏ inputs. A demultiplexer routes one input to a selected destination. These operations choose paths; they do not store a value without a separate state element.",
  "A decoder converts an encoded input into a one-hot selection, often qualified by an enable. Memory address decoding, instruction decoding, and display control use this pattern. An encoder performs a reverse mapping; if multiple inputs may be asserted, a priority encoder must define which one wins and indicate whether any valid input exists.",
  "A multiplexer can implement an arbitrary Boolean function by making some variables select inputs and filling data inputs with constants or functions of the remaining variables. Seven-segment decoding adds an output convention: common-anode and common-cathode displays use different electrical polarities even though the intended digit is the same."
], "2:1 multiplexer: Y = S′D₀ + SD₁; k select bits address 2ᵏ choices", ["Use A and B as selects for a 4:1 mux implementing XOR.", "Rows 00, 01, 10, 11 require outputs 0, 1, 1, 0.", "Wire D₀=0, D₁=1, D₂=1, D₃=0. The mux now computes A ⊕ B."], ["A decoder is not a register.", "An ordinary encoder needs a defined policy when more than one input is active."], "How many select bits does an 8:1 mux need?", "Three, because 2³ = 8."),
chapter("timing", "Clocks, setup, hold, and metastability", "clock timing setup hold metastability skew jitter waveform synchronizer", [
  "A synchronous circuit moves data between registers through combinational logic. The clock establishes capture events. Setup time requires data to be stable before the capturing edge; hold time requires stability after it. These are constraints around the edge, not extra software steps.",
  "The maximum combinational delay limits the shortest clock period after including clock-to-Q, setup, and uncertainty. Minimum delay matters separately for hold. Clock skew shifts the relative launch and capture edges, helping one constraint while potentially hurting the other. Increasing the period can fix setup failure but usually does not repair a same-edge hold failure.",
  "An asynchronous input can violate the capture window and put a flip-flop into metastability, an analog state whose settling time is uncertain. A synchronizer provides time for resolution and greatly reduces the probability of failure; it never makes that probability mathematically zero. Multi-bit values need a protocol, FIFO, or appropriate encoding rather than independent synchronizers alone."
], "Ignoring skew: Tclock ≥ tCQ,max + tlogic,max + tsetup; hold: tCQ,min + tlogic,min ≥ thold", ["Let clock-to-Q be 1 ns, combinational delay 6 ns, and setup 1 ns.", "The minimum period before margin is 8 ns, so maximum frequency is 125 MHz.", "Adding 1 ns uncertainty raises the period to 9 ns, about 111 MHz."], ["A slower clock does not generally fix hold timing.", "Simulation’s X is a model of uncertainty, not a literal third voltage level."], "Why use two flip-flops to synchronize a single asynchronous control bit?", "The first may become metastable. A full cycle before the second captures gives it time to settle, reducing the chance of propagation."),
chapter("storage", "Latches, flip-flops, and registers", "latch flip-flop flip flop dff sr jk master slave register siso sipo piso pipo shift universal", [
  "Storage adds memory to logic: the output depends on previous state as well as inputs. A latch is level sensitive and follows data while its enable is active. An edge-triggered flip-flop samples at a clock transition and holds between transitions. Calling both a register can hide an important timing distinction.",
  "The D flip-flop has next-state equation Q⁺ = D. SR adds set/reset behavior with a forbidden input combination in the elementary implementation. JK replaces that case with toggle, while T directly selects hold or toggle. Characteristic tables predict the next state; excitation tables determine inputs needed for a desired transition.",
  "A word register is several storage bits sharing controls. A mux in front of each D input selects hold, load, or a neighbor for shifting. Serial and parallel names describe interfaces: SIPO collects serial bits into a word, while PISO loads a word and emits one bit per clock. Direction, bit order, and the moment of observation must be stated explicitly."
], "D: Q⁺=D; T: Q⁺=T⊕Q; JK: Q⁺=JQ′+K′Q; enabled register: Q⁺=E·D+E′·Q", ["Load 1011 into a four-bit register.", "Perform a logical right shift with serial input zero: 1011 → 0101.", "A second shift gives 0010. The outgoing least significant bits were 1 then 1."], ["Changing D does not change an edge-triggered Q without a capture edge.", "An SR forbidden combination depends on whether inputs are active-high or active-low."], "How does an enabled D register hold its word?", "The input mux selects the current Q as the next D when enable is zero."),
chapter("fsm", "Counters and finite state machines", "state fsm moore mealy counter mod decade ring johnson encoding minimize excitation", [
  "An FSM describes behavior using a current state, inputs, a next-state function, and outputs. A Moore output depends on state; a Mealy output depends on state and current input. Both require complete rules for the input cases the system can encounter, including reset and unexpected states.",
  "A counter is a restricted FSM with a regular sequence. A binary n-bit counter naturally wraps modulo 2ⁿ. A MOD-N design must return after N legal states and handle unused encodings. Ripple counters use one stage’s output as another stage’s clock; synchronous counters share a clock and compute enables combinationally.",
  "State encoding maps abstract states to bits. Binary uses ceil(log₂ S) state bits, while one-hot uses S bits with simpler local decoding. State minimization merges states only if they are behaviorally indistinguishable for every future input sequence. Fewer encoded bits do not automatically mean fewer gates or a faster design."
], "Next state: S⁺=f(S,X); Moore: Y=g(S); Mealy: Y=g(S,X)", ["Design a MOD-3 counter with states 00 → 01 → 10 → 00.", "Two flip-flops provide four encodings, so 11 is unused.", "Define 11 → 00 for recovery, then derive next-state equations from all four rows."], ["A ring needs initialization; an all-zero ordinary ring stays zero.", "Mealy outputs can react between clock edges when inputs change."], "How many binary-encoded flip-flops are needed for five states?", "Three, since two bits provide only four codes and three provide eight."),
chapter("memory", "Addressed memory and hierarchy", "memory ram rom sram dram hierarchy locality array address bank row buffer", [
  "Memory associates an address with a stored word. An address selects a location, while the data width specifies how many bits are returned or written. Capacity is the number of locations times bits per location. Byte-addressed and word-addressed systems differ in what one address increment means.",
  "SRAM uses a bistable cell and retains data while powered without periodic refresh. DRAM stores charge and requires refresh; row activation and precharge are part of access cost. ROM and nonvolatile technologies retain information under different programming and endurance constraints. Read latency, throughput, capacity, and energy are separate characteristics.",
  "Hierarchy exploits locality. Temporal locality means recently used data may be used again; spatial locality means nearby addresses may be needed. Small, fast levels keep copies of useful data backed by larger, slower levels. An access may spend time at several levels, so a single label such as ‘RAM speed’ cannot explain total performance."
], "Capacity = 2ᵃ × w bits for a address bits and w bits/location", ["A 1K × 16 memory has 1024 locations, each 16 bits wide.", "It needs 10 address bits and stores 16,384 bits = 2048 bytes.", "If mapped into a byte-addressed system, each 16-bit word occupies two byte addresses."], ["A memory address and the value stored there are different quantities.", "DRAM row hits and row conflicts do not have identical latency."], "Why does a sequential array scan often benefit from spatial locality?", "Fetching one line supplies several adjacent elements, which the scan soon accesses." , ["ostep"]),
chapter("cache", "Caches, mapping, replacement, and writes", "cache hit miss tag index offset lru fifo write associativity amat", [
  "A cache keeps memory blocks close to a processor. The block offset selects bytes inside a line; the set index selects candidate lines; tags identify which memory block currently occupies each candidate. A valid bit distinguishes meaningful contents from an unused slot. A hit requires both valid and matching tag.",
  "Direct mapping allows one candidate location, set associativity allows several ways in a set, and full associativity allows any line. Replacement chooses a victim when no invalid way is available. LRU approximates temporal locality; FIFO tracks insertion order. Compulsory, capacity, and conflict misses explain different causes and respond to different design changes.",
  "Write-through forwards writes to the next level, while write-back marks a line dirty and defers its propagation until eviction or another coherence action. Write-allocate and no-write-allocate specify handling of write misses. These are independent choices. A hit ratio alone is insufficient: miss penalty, access time, bandwidth, and dirty evictions all matter."
], "AMAT = hit time + miss rate × miss penalty; sets = cache bytes/(line bytes × ways)", ["Take a 1 KiB cache with 16-byte lines and 4 ways.", "There are 1024/(16×4)=16 sets. Offset needs 4 bits; set index needs 4 bits.", "For a 32-bit byte address, the remaining 24 bits form the tag."], ["A cache miss is not a page fault.", "Higher associativity reduces many conflict misses but does not eliminate compulsory or capacity misses."], "With a 2 ns hit time, 5% misses, and 80 ns extra miss penalty, what is AMAT?", "2 + 0.05 × 80 = 6 ns. The penalty is assumed additional to the initial hit lookup." , ["ostep"]),
chapter("vm", "Virtual addresses, paging, and protection", "virtual page tlb translation protection page fault address space", [
  "Virtual memory separates a program’s addresses from physical locations. A virtual address divides into virtual page number and page offset. A page-table entry maps that page to a physical frame and records permissions and status. Translation changes the page number while retaining the offset.",
  "A TLB caches recent translations, not the underlying data. On a TLB miss, hardware or software locates the page-table entry. If the mapping is present and permitted, execution can continue after filling the TLB. A page fault instead enters the operating system because the access cannot currently complete under the mapping or protection rules.",
  "Multi-level page tables avoid allocating a flat entry for every possible virtual page in a sparse address space. Page sizes trade translation reach and table size against internal fragmentation and flexibility. Protection is checked on accesses: a mapped address may still be non-writable or non-executable. An IOMMU supplies related translation and protection for device accesses."
], "Physical address = frame number × page size + page offset", ["With 4 KiB pages, the low 12 bits are the offset.", "Virtual address 0x1234 has page number 1 and offset 0x234.", "If virtual page 1 maps to physical frame 9, the physical address is 0x9234."], ["TLB misses need not involve disk I/O.", "A virtual address that fits the width is not necessarily mapped or authorized."], "Does changing the page mapping change the offset within a page?", "No. Translation replaces the page number; the page offset is preserved." , ["ostep"]),
chapter("cpu", "Datapath, register transfer, and instruction execution", "cpu datapath register transfer rtl fetch decode execute pc mar mdr ir register file word bus", [
  "A processor transforms architectural state according to instructions. The datapath contains registers, arithmetic units, muxes, and connections. The control unit chooses which transfers and operations occur. The ISA describes visible behavior; the microarchitecture decides the internal sequence that implements it.",
  "The program counter identifies an instruction location. Fetch reads instruction memory into an instruction register; decode identifies the operation and operands; execute performs arithmetic, accesses memory, or changes control flow. MAR and MDR are useful teaching registers for address and data paths, though a real implementation may organize or name them differently.",
  "Register-transfer notation describes simultaneous updates at a clock boundary. In R1 ← R2 + R3, the source values are read from the old state and the destination receives the result on the capture event. A shared bus can carry only one driven value at a time; additional transfers require another path or another cycle."
], "Rdest⁺ = f(Rsrc1, Rsrc2); sequential PC = PC + instruction length", ["For LOAD R1, [R2+4], first read the old R2.", "Compute the effective address R2+4, read the memory word, and route it to R1.", "Write R1 only when the memory response is valid. A load is more than merely drawing an ALU arrow."], ["A clock cycle and a completed instruction are not the same unit.", "Simultaneous register updates use old source values, not partially updated values."], "Why does a single shared bus sometimes require multiple microsteps?", "Different source values cannot drive the same bus simultaneously; intermediate storage and sequencing are required."),
chapter("isa", "Instructions, encodings, and addressing modes", "isa instruction opcode encoding format addressing immediate indirect risc cisc mips riscv arm x86 assembly", [
  "An instruction set is the contract between software and a processor: operations, registers, data types, memory behavior, exceptions, and encodings. An encoding divides instruction bits into fields. An opcode names an operation; register fields select operands; immediate or displacement fields carry constants.",
  "Addressing modes describe where an operand comes from. Immediate uses bits inside the instruction; register addressing uses a register value; base-plus-displacement computes a memory address. Indirect addressing follows an address stored elsewhere. PC-relative branches add a displacement according to the ISA’s specified base and scaling rules.",
  "Assembly uses mnemonics, labels, and directives to produce machine code. A label denotes an address rather than an extra runtime instruction. An ABI adds software conventions such as argument registers and stack layout. RISC and CISC describe families of design choices, not reliable performance rankings; comparisons require the same task, implementation assumptions, and measurement conditions."
], "Base-displacement effective address: EA = base register + sign-extended displacement", ["Suppose R2 contains 0x1000 and a load has displacement 12.", "The effective byte address is 0x100C, assuming a byte displacement in this teaching format.", "The loaded value is the memory contents at that address, not 0x100C itself."], ["An instruction field’s width and the operand’s data width may differ.", "Do not apply one ISA’s branch offset or carry convention to another ISA."], "What distinguishes an immediate constant from a memory address?", "An immediate is a value encoded in the instruction. An address identifies a memory location whose contents may be fetched." , ["riscv", "mit"]),
chapter("control", "Hardwired and microprogrammed control", "control microcode microprogram hardwired sequencer microinstruction", [
  "Control converts the instruction and current machine state into mux selections, enables, memory requests, and next-step choices. A datapath with perfect arithmetic still cannot execute correctly if a destination enable fires too early or two bus drivers are enabled together.",
  "Hardwired control builds these choices from logic and state machines. Microprogrammed control stores control words in a control memory and uses a microsequencer to choose the next word. Horizontal microcode exposes many independent control bits; more encoded formats save control-memory width but need decoding.",
  "Conditional sequencing uses information such as opcode, zero flags, or memory-ready status. A memory wait state must preserve the request and avoid accidental repeated architectural updates. Microinstructions are implementation steps, not the same thing as ISA instructions. Both hardwired and microprogrammed designs can implement the same ISA."
], "Control outputs = g(opcode, microstate, flags, ready); next microstate = f(current microstate, conditions)", ["A fetch sequence can begin with MAR ← PC.", "Assert memory read and wait until ready; then capture IR ← memory data and advance PC.", "Dispatch using the decoded opcode to the corresponding execute sequence."], ["A control-memory address is not a program-counter address.", "Holding a write-enable during a wait may repeat an operation if the interface does not suppress it."], "Can changing microcode change the instruction encoding?", "It can change an implementation, but software compatibility requires preserving the ISA contract unless deliberately defining a new ISA."),
chapter("pipeline", "Pipelining, hazards, and prediction", "pipeline hazard forwarding stall branch prediction throughput latency fde", [
  "Pipelining overlaps stages from different instructions. A common teaching pipeline uses fetch, decode, execute, memory, and writeback. It increases steady-state throughput when stages can work concurrently; an individual instruction still traverses all its required stages.",
  "A structural hazard means instructions need the same resource. A data hazard means an instruction needs a value not yet available. Forwarding routes a produced result directly to a consumer, but cannot send a load value before memory has produced it. A stall holds dependent work and inserts a bubble where needed.",
  "A control hazard arises because the next fetch address depends on a branch or jump. Prediction lets fetch proceed speculatively; a wrong prediction flushes younger wrong-path work. Precise recovery must prevent that work from committing architectural side effects. Deeper pipelines can raise frequency while increasing misprediction cost and control complexity."
], "Ideal cycles for N instructions and k one-cycle stages: N + k − 1; CPU time = instructions × CPI × cycle time", ["Run ten independent instructions through five ideal stages.", "The first completes after five cycles; the remaining nine complete one per cycle.", "Total is 14 cycles, compared with 50 for a non-overlapped five-cycle implementation. Speedup is 50/14 ≈ 3.57."], ["Pipeline stage count is not the speedup for every program.", "Forwarding reduces many RAW stalls but does not erase all dependencies."], "Why might an immediate consumer of a load still stall?", "Its operand is needed before the memory stage has produced the loaded data, even if forwarding paths exist."),
chapter("ooo", "Instruction-level parallelism and precise retirement", "scoreboard tomasulo reorder renaming superscalar reservation station out-of-order ilp raw war waw", [
  "Independent instructions can execute simultaneously on multiple functional units. The processor must respect true read-after-write dependencies while avoiding unnecessary ordering. Write-after-read and write-after-write conflicts arise from reusing names and can often be removed with register renaming.",
  "A scoreboard tracks resource use and dependencies centrally. Tomasulo-style scheduling uses reservation stations and producer tags to wait for operand values. Renaming maps architectural registers onto a larger pool of physical destinations. These mechanisms expose parallelism but cannot remove a true dependency on an unfinished computation.",
  "A reorder buffer or equivalent retirement mechanism commits instructions in program order even when execution finishes out of order. If an exception or misprediction occurs, younger speculative results can be discarded. Stores need particular care: globally visible memory updates cannot be casually undone after other agents have observed them."
], "IPC = retired instructions/cycles; CPI = cycles/retired instructions for the same measured interval", ["I1 writes R1. I2 reads R1 and writes R2. I3 writes a new R1 independently.", "Rename I1’s destination to P7 and I3’s to P8; I2 keeps its dependence on P7.", "I3 can execute early without overwriting the value I2 needs. I2 still waits for I1’s true result."], ["Renaming removes name dependencies, not RAW data dependencies.", "Execution completion does not imply architectural retirement."], "Why retire in order if execution is out of order?", "It provides an architectural state corresponding to a precise program boundary for exceptions and recovery."),
chapter("interrupt", "Interrupts: from request to return", "interrupt irq timeline service routine isr context save return", [
  "An interrupt lets hardware request processor attention without forcing software to poll continuously. A device controller records the event and signals an interrupt controller or CPU. Delivery depends on pending state, masking, priority, and the processor’s current execution context. The event and the moment it is serviced are different times.",
  "On acceptance, the machine preserves the state required by its architecture, identifies a handler, and transfers control. A software entry routine may save additional registers. The ISR determines the cause, services the device, and acknowledges or clears the source according to its protocol. Leaving a level-triggered cause asserted can cause immediate redelivery.",
  "Return restores the saved execution context. The saved PC’s meaning depends on the event and ISA, so a diagram’s ‘next instruction’ must not be treated as a universal rule. Interrupt latency includes masking, higher-priority work, entry overhead, and software work before the device is serviced. Keep the urgent handler short and defer longer work when the system provides a mechanism."
], "Response latency = acceptance delay + entry overhead + time until service action", ["A timer becomes pending while ordinary instructions execute.", "At an allowed boundary, the CPU saves return state and looks up the timer handler.", "The handler clears the timer condition and updates software state; interrupt return restores the interrupted context."], ["An interrupt does not itself copy a device’s entire data buffer.", "Acknowledging the controller and clearing the device’s cause may be separate actions."], "Why can an interrupt fire again immediately after return?", "A pending event may remain, or a level-triggered device may still assert its request because its cause was not cleared." , ["ostep", "riscv"]),
chapter("priority", "Masking, arbitration, and nested interrupts", "interrupt priority mask arbitration nested arbiter vector controller", [
  "Multiple devices may request service simultaneously. An interrupt controller filters eligible requests and chooses a winner under a priority policy. Priority numbers are conventions: a smaller number can mean higher priority in one model and the opposite in another. The lab must state its rule.",
  "Masking suppresses delivery of selected maskable interrupts, usually without erasing the event itself. Pending, enabled, and active are distinct states. Nesting allows a higher-priority request to preempt a lower-priority handler if both the architecture and entry software support it. Each nested entry needs safe context storage and a well-defined return path.",
  "Fixed priority minimizes response time for chosen critical sources but can starve lower-priority devices. Rotating priority improves fairness. Real systems also use affinity, interrupt moderation, and deferred processing. Non-maskable events have special delivery rules; they are not simply ordinary interrupts with a checkbox permanently enabled."
], "Eligible request = pending AND enabled AND permitted by current priority threshold", ["Assume smaller numbers mean higher priority: Timer=0, Network=2, Keyboard=4.", "With all three pending and enabled, Timer wins.", "Mask Timer and Network becomes the next eligible winner; Timer can remain pending."], ["Masked does not necessarily mean discarded.", "Nesting depth and context-save overhead consume stack and execution time."], "Does the highest priority number always win?", "No. Number ordering is architecture-specific; use the stated priority convention." , ["riscv", "ostep"]),
chapter("vectors", "Vectors, exceptions, and precise machine state", "vector exception trap fault divide illegal protection synchronous", [
  "A vector associates an event identifier with an entry point or entry rule. A vector may select an address-table entry, an instruction slot, or a common handler that reads a cause register. Vectored interrupt delivery does not universally mean every handler has a hardcoded immutable address.",
  "An exception is synchronous with instruction execution: an invalid opcode, a protection violation, or an arithmetic condition defined by the ISA. An external interrupt is asynchronous to that instruction stream. Terminology such as fault, trap, abort, and software interrupt varies across architectures, so compare semantics rather than labels alone.",
  "A precise exception presents a state in which older instructions have completed and the faulting instruction and younger work are handled according to the architecture’s rules. A recoverable page fault may retry an instruction after fixing its mapping. An invalid instruction may terminate the process. Saving a PC does not imply every exception can safely resume by incrementing it."
], "Simple address-table model: entry address = vector base + event number × entry size", ["Take vector base 0x1000 and four-byte table entries.", "Event 5 selects the entry at 0x1014. If that entry contains 0x2000, the handler address is 0x2000.", "The address of the table entry and the handler address stored there are different."], ["Exceptions are not all external device interrupts.", "A vector index is not automatically the handler’s memory address."], "Why might a page-fault handler retry the same instruction?", "It can install the required mapping, then restart the operation that could not previously complete." , ["riscv", "ostep"]),
chapter("dma", "DMA: data movement, ownership, and completion", "dma direct memory transfer block device controller buffer", [
  "Direct memory access moves a block between memory and a device, or between memory regions, without a CPU instruction copying every item. Software still allocates and prepares buffers, configures source, destination, direction, and length, submits the operation, and handles completion or errors. DMA reduces CPU involvement; it does not remove it.",
  "The transfer engine requests interconnect access and issues reads and writes. Burst mode transfers multiple items together; cycle stealing interleaves transfers with other masters. The CPU may continue independent work, subject to contention and the system’s memory architecture. A teaching diagram that gives DMA sole bus ownership models one arbitration policy rather than every modern system.",
  "Correctness requires agreement about buffer ownership and visibility. Cache contents may need synchronization on noncoherent systems. A device DMA address can differ from a CPU virtual or physical address because of an IOMMU or bus mapping. Completion means the protocol’s promised work is finished, after which software can safely consume the result using the required synchronization rules.",
  "DMA is most useful when setup cost is amortized over a sufficiently large transfer. Small transfers can be cheaper with programmed I/O. Interrupts and DMA cooperate: DMA carries data; an interrupt can announce that the transfer has completed. Polling a completion queue is another possible notification method."
], "Ttransfer ≈ Tsetup + bytes/effective bandwidth + Tcompletion; CPU work is separate from elapsed transfer time", ["Move 4096 bytes with 10 µs setup, 1 GB/s effective bandwidth, and 2 µs completion overhead.", "Transfer time is 4.096 µs, giving about 16.096 µs total under this simplified non-overlapping model.", "If the CPU does unrelated work during the transfer, elapsed time is not equal to CPU busy time."], ["DMA does not imply the CPU is idle for the entire transfer.", "Do not reuse or free a buffer before completion; cache coherence and completion are different concerns."], "Why can DMA still use a completion interrupt?", "DMA performs the bulk transfer; the interrupt tells software when the result is ready without continuous polling." , ["dma", "ostep"]),
chapter("io", "Programmed I/O, device registers, and polling", "i/o io interface polling memory-mapped isolated peripheral device status", [
  "A device controller exposes registers for data, status, and commands. The processor communicates through an interface rather than directly manipulating the physical peripheral. Memory-mapped I/O places registers in the load/store address space; isolated I/O uses a separate access mechanism defined by the ISA.",
  "Programmed I/O uses CPU instructions to move each data item. Polling repeatedly reads status until a device is ready. This can be appropriate for a short predictable wait or a dedicated high-rate loop, but a long busy-wait consumes CPU time. Interrupt-driven service avoids constant checking while adding event-delivery and handler overhead.",
  "Device accesses may have side effects: a read can remove a FIFO item, and writing a one may clear a status bit. Compiler treatment, memory ordering, and access width must match the device contract. A normal memory assignment is not sufficient evidence that a hardware register protocol is correct."
], "Polling CPU time ≈ number of polls × cost per poll + data-copy work", ["A receive-status register has a READY bit and a data register holds one byte.", "Read status until READY is set, then read the data register once and store that byte.", "If the data register consumes the item on read, a second diagnostic read may remove the next byte."], ["Memory-mapped does not mean device registers behave like ordinary RAM.", "Interrupt-driven I/O may still copy data using the CPU."], "When can polling be reasonable?", "When waits are very short or a dedicated loop services a high event rate efficiently, provided the CPU cost and fairness are acceptable." , ["ostep"]),
chapter("bus", "Buses, arbitration, and bandwidth", "bus interconnect noc network-on-chip arbitration bandwidth latency packet mesh", [
  "An interconnect carries requests and responses between masters and targets. A traditional bus separates address, data, and control roles. A master initiates a transaction; a target responds. Modern fabrics may use multiple channels, switches, packets, and several simultaneous transfers rather than one electrically shared wire bundle.",
  "Arbitration decides among competing requests. Fixed priority, round robin, and weighted policies trade response guarantees against fairness. A grant gives permission to use a resource; the transfer still needs a valid protocol and a ready target. Backpressure prevents a sender from overrunning the next stage.",
  "Bandwidth measures data per unit time; latency measures delay for an operation. Wider links and faster clocks raise peak bandwidth, but protocol overhead, contention, turnarounds, and unused cycles reduce the delivered rate. A network-on-chip distributes traffic across routers and links, introducing routing and congestion questions."
], "Peak bandwidth = data width in bytes × transfers per cycle × clock frequency", ["A 64-bit link carrying one transfer per 100 MHz cycle has 8 × 100 million = 800 MB/s peak bandwidth.", "At 75% useful utilization, delivered bandwidth is 600 MB/s.", "A 1 MB payload therefore needs about 1.67 ms, before any separate startup latency."], ["A 64-bit address bus and a 64-bit data bus describe different widths.", "Peak bandwidth is an upper bound under stated transfer assumptions."], "Can high bandwidth coexist with high latency?", "Yes. A link can deliver large blocks quickly once started but still take a long time to return the first result."),
chapter("coherence", "Coherence, consistency, and synchronization", "coherence mesi msi moesi multicore false sharing consistency atomic synchronization lock fence", [
  "Private caches can hold copies of the same memory line. Coherence ensures that processors agree on writes to each location under the protocol’s rules. MSI tracks modified, shared, and invalid states; MESI adds exclusive clean ownership to avoid some unnecessary traffic. A write generally requires exclusive permission and invalidation of conflicting copies.",
  "Memory consistency specifies allowed ordering observations across different locations. It is separate from coherence. A weakly ordered machine can be coherent while allowing outcomes a simple sequential interleaving would forbid. Acquire, release, and fences constrain relevant ordering when used through the language and ISA memory models.",
  "Atomic read-modify-write operations indivisibly combine a read and update. They support locks and counters, but contention still costs time. False sharing occurs when unrelated variables occupy one coherence line: independent writers invalidate each other’s copies despite not sharing a logical variable. Padding or reorganizing data can reduce this traffic."
], "False sharing unit = coherence line, not source-language variable", ["Core 0 writes variable A and Core 1 writes B, both inside one 64-byte line.", "Each needs write permission for the whole line, causing repeated ownership transfers.", "Move A and B to different lines and measure whether coherence traffic and runtime decrease."], ["Coherence does not imply sequential consistency.", "An atomic flag without the required ordering does not automatically publish preceding ordinary writes."], "Why can two independent counters contend?", "They can share a cache line and repeatedly transfer exclusive ownership between cores." , ["ostep", "riscv"]),
chapter("performance", "Performance models and bottlenecks", "performance amdahl roofline cpi ipc speedup counter scaling efficiency benchmark", [
  "Performance claims need a workload, metric, and baseline. CPU time depends on instruction count, cycles per instruction, and cycle time. Improving one factor may worsen another. Latency describes one task’s completion time, whereas throughput counts tasks completed per interval.",
  "Amdahl’s law bounds acceleration when only part of a workload improves. A serial fraction remains even with unlimited parallel resources. Communication, imbalance, synchronization, and memory traffic add overhead beyond the ideal model. Parallel efficiency divides speedup by the number of workers.",
  "The roofline model compares arithmetic intensity, measured as operations per byte moved at a specified memory boundary, with peak compute and bandwidth. It predicts an upper bound rather than guaranteed performance. Counters help test a bottleneck hypothesis, but event definitions and overlapping stall categories require care."
], "Speedup = 1/((1−p)+p/s); roofline bound = min(peak operations/s, bandwidth × operations/byte)", ["If 80% of execution can use four cores ideally, p=0.8 and s=4.", "Speedup is 1/(0.2+0.8/4)=2.5, not 4.", "With infinitely fast parallel work, the serial 20% still limits speedup to 5."], ["Clock frequency alone is not an application performance metric.", "Do not add overlapping stall counters as if they were disjoint categories."], "A workload has intensity 2 FLOP/byte and bandwidth 50 GB/s. What is its bandwidth roof?", "100 GFLOP/s, assuming decimal units and the specified memory traffic boundary."),
chapter("accelerator", "Accelerators, matrix products, and data reuse", "accelerator mac systolic tensor matrix npu gpu tpu dataflow stationary neural inference training mixed precision", [
  "A multiply-accumulate unit computes a product and adds it to a running sum. Dot products repeat that operation; matrix multiplication repeats dot products across rows and columns. Parallel MAC arrays increase potential throughput, provided memory and interconnect can feed operands at the required rate.",
  "A systolic array passes operands between neighboring processing elements on a schedule. Weight-stationary, output-stationary, and activation-stationary describe which values stay local for reuse. The best choice depends on tensor shape, local storage, and traffic costs, not merely the number of multipliers.",
  "Narrow arithmetic reduces storage and transfer demand but introduces range and precision constraints. Accumulation may use more bits than multiplication. Inference evaluates a model using fixed weights; training also needs gradients, optimizer state, and saved activations. Accelerator speedup must include launch, transfer, synchronization, and unsupported operations."
], "Cᵢⱼ = Σₖ AᵢₖBₖⱼ; m×k by k×n multiplication uses mkn multiply-accumulates", ["Multiply [1,2] by the column [3,4]. Start the accumulator at zero.", "First MAC gives 0+1×3=3. Second gives 3+2×4=11.", "Two MACs produce one output; an array changes scheduling and reuse, not this result."], ["Peak TOPS assumes particular precision and operation-count conventions.", "Adding more MACs cannot overcome an unchanged operand bandwidth bottleneck."], "Why keep partial sums local?", "It avoids repeatedly transferring the same output accumulation to a more expensive memory level."),
chapter("soc", "Heterogeneous systems and complete SoCs", "soc heterogeneous mobile desktop cpu cluster gpu dsp offload power domain thermal chiplet package", [
  "A system-on-chip integrates processors, memory interfaces, accelerators, peripheral controllers, and interconnect. A CPU handles general control flow; specialized engines often execute regular data-parallel or signal-processing work more efficiently. These are architectural tendencies rather than universal rankings.",
  "Offloading a job requires preparing data, submitting work, waiting for dependencies, and obtaining results. Separate memory may require copies. Unified addressing simplifies naming, but does not remove bandwidth, cache visibility, migration, or synchronization costs. Model the application as a graph of dependent tasks and find its critical path.",
  "Clock domains, power domains, and thermal limits shape operation. Clock gating reduces switching while retaining powered state. Power gating removes supply from a domain and may require retention and isolation. Frequency changes and thermal throttling make sustained behavior differ from a brief peak measurement."
], "Offload helps when Tprepare + Ttransfer + Taccelerator + Tsync < TCPU", ["A CPU task needs 10 ms. An accelerator needs 2 ms, plus 3 ms transfer and 1 ms synchronization.", "Total offload time is 6 ms, a speedup of about 1.67.", "If the task shrinks until CPU execution is 1 ms but transfer overhead remains 4 ms, offload loses."], ["Unified memory is not infinite-bandwidth memory.", "Clock gating and power gating have different state-retention and wake-up costs."], "Why can a fast accelerator be a poor choice for a tiny task?", "Submission, copies, and synchronization may cost more than the computation it saves."),
chapter("embedded", "Microcontrollers and firmware execution", "microcontroller mcu embedded firmware bare-metal arduino 8051 pic avr stm32 esp32 register sfr harvard von neumann stack bootloader debugger", [
  "A microcontroller combines a processor with program memory, working RAM, clocks, timers, and peripheral interfaces. Firmware controls the whole device rather than merely computing a result. Flash stores program code, SRAM holds live state, and a stack supports calls, local data, and interrupt context according to the ABI.",
  "Reset establishes an initial execution context before ordinary application code. Startup typically initializes the stack, copies initialized data to RAM, clears zero-initialized storage, configures the required clocks, and enters the application. Exact details depend on the MCU and toolchain. Memory-mapped special-function registers control peripherals with documented bit-level semantics.",
  "A reliable firmware loop separates sensing, decision making, and outputs. Blocking delays simplify a first experiment but prevent other work from progressing. Timers, event queues, interrupt handlers, and state machines support responsiveness. A debugger’s paused state can change real-time behavior, so traces and external observations are useful complements."
], "Execution budget per event = available clock cycles before deadline − other required work", ["At a 16 MHz clock, a 1 ms period contains 16,000 cycles.", "If sampling and control take 4,000 cycles, the raw budget remaining is 12,000 cycles.", "Reserve time for interrupts, variable paths, and overhead rather than scheduling the full theoretical budget."], ["A processor’s word size does not directly specify its addressable memory capacity.", "Writing a peripheral register requires its documented width and side-effect rules."], "Why is SRAM usually used for the stack?", "The stack changes frequently during calls and interrupts, so it needs writable memory with low-latency access."),
chapter("gpio", "GPIO, electrical interfaces, and debouncing", "gpio digital input output pin multiplex alternate pull resistor led keypad debounce", [
  "A GPIO pin can sense an external logic level or drive an output, subject to configuration and electrical limits. Direction, input buffering, pull resistors, and alternate-function selection are separate controls. A pin routed to a peripheral may no longer obey the ordinary GPIO output latch.",
  "A floating input has no stable guaranteed value. Pull-up and pull-down resistors provide a default level while allowing an external switch or open-drain driver to override it. Open-drain outputs actively pull low and otherwise release the line. Current-limiting resistors and appropriate drivers are needed for loads that exceed pin capability.",
  "Mechanical switches bounce, creating several transitions during one press. Debouncing accepts a change only after a stable interval or through a suitable hardware filter. An interrupt-on-edge setting alone does not distinguish bounce from several genuine presses. Synchronization and debouncing solve different problems."
], "Resistor current: I = (Vsupply − Vload)/R; port update with mask: new = (old AND NOT mask) OR value", ["Connect a switch from input to ground and enable a pull-up.", "Released reads one; pressed reads zero. The software should treat the input as active-low.", "Accept a press after the level remains low for the chosen debounce interval."], ["Input pull-up does not make a pin a strong power source.", "A read-modify-write on a shared port can race with an ISR; use atomic set/clear facilities where available."], "Why do open-drain buses need pull-ups?", "Drivers only pull the line low. The pull-up establishes the high level when all drivers release it."),
chapter("timers", "Timers, PWM, capture, and motor control", "timer counter pwm capture compare servo motor stepper motion rtc watchdog", [
  "A hardware timer counts a clock or external events, often after a prescaler. Overflow and compare matches can generate an interrupt or change an output without software toggling the pin at every edge. Timer resolution and maximum interval depend on clock, prescaler, and counter width.",
  "PWM controls the proportion of time an output is active. Frequency sets the repetition rate; duty cycle sets the active fraction. A motor driver converts these signals into suitable voltage and current. A hobby servo interprets pulse timing as a command; its control scheme is different from simply applying a duty percentage to a DC motor.",
  "Input capture records a counter value at an input edge, allowing period or pulse-width measurements with less ISR timing error. Output compare schedules an edge at a chosen counter value. Watchdogs detect firmware that fails to report progress; refreshing a watchdog from an unconditional timer interrupt can conceal a stalled application."
], "Timer tick = prescaler/fclock; up-counter PWM period = (TOP+1) × tick; duty = active ticks/period ticks", ["With a 16 MHz clock and prescaler 8, each tick lasts 0.5 µs.", "Using 2000 ticks per period yields 1 ms, or 1 kHz.", "An output active for 500 ticks has 25% duty cycle."], ["The exact TOP and compare off-by-one rules depend on the timer mode.", "An MCU pin should not drive a motor winding directly."], "Why is capture more accurate than reading a timer later in an ISR?", "Hardware latches the count at the edge, avoiding variable delay before the handler reads it."),
chapter("analog", "Sampling, ADCs, DACs, and sensor calibration", "adc dac analog comparator resolution quantization sensor temperature thermometer voltage acquisition", [
  "An ADC maps a sampled analog input into a finite digital code. Resolution sets the number of available codes; reference voltage sets their voltage scale. Accuracy also depends on offset, gain error, noise, reference stability, and input settling. More output bits do not guarantee proportionally more useful information.",
  "Sampling converts a continuous signal into observations in time. To avoid aliasing for a bandlimited signal, the sampling rate must exceed twice the highest retained frequency, with a practical transition band for the anti-alias filter. A sample-and-hold needs enough acquisition time for the source and input capacitance to settle.",
  "Calibration maps electrical measurements to physical units using a sensor model, reference points, or a lookup table. A DAC performs a complementary reconstruction step, producing discrete analog levels that may need filtering. A comparator reports which of two voltages is greater; it is not a multi-bit ADC."
], "Ideal ADC step ≈ Vref/2ⁿ; calibrated measurement = scale × code + offset", ["A 12-bit ADC with 3.3 V reference has 4096 codes and a nominal 0.806 mV step.", "For an ideal sensor with 10 mV/°C and zero offset, 250 mV corresponds to 25°C.", "Real calibration must account for sensor offset, gain, ADC error, and reference uncertainty."], ["Quantization resolution is not total measurement accuracy.", "Aliased high-frequency content cannot generally be removed after it has folded into the sampled band."], "What happens to voltage per code if the reference is halved at the same bit depth?", "It halves, but the measurable voltage range also halves."),
chapter("serial", "Serial protocols and communication interfaces", "uart serial spi i2c i²c can usb communication baud framing", [
  "A serial interface sends a sequence of bits over time. UART frames asynchronous data with start and stop bits and depends on agreement about baud rate and format. SPI uses a shared clock with controller-selected targets. I²C uses addressed transactions on shared open-drain data and clock lines.",
  "Protocol timing matters as much as bit values. UART receivers sample near expected bit centers. SPI’s clock polarity and phase determine which edges launch and capture data. I²C uses start, address, acknowledgment, data, and stop rules, with pull-up rise time limiting achievable speed. CAN adds arbitration and error handling; USB uses a considerably richer layered protocol.",
  "Buffers decouple software scheduling from wire timing but have finite capacity. A receive overrun loses information when software or DMA cannot drain data fast enough. Timeouts, error status, and framing recovery are part of a complete driver. The application payload rate is lower than the raw signaling rate because of protocol overhead."
], "UART 8-N-1 payload rate ≈ baud × 8/10 bits/s", ["At 9600 baud, 8-N-1 sends one start bit, eight data bits, and one stop bit per byte.", "Each byte occupies 10 bit times, so maximum sustained payload is about 960 bytes/s.", "A 96-byte message needs about 100 ms before software gaps or higher-level framing."], ["Matching baud rate is insufficient if parity or stop-bit configuration differs.", "SPI chip-select and clock mode are part of the target’s contract."], "Why is a 115200-baud UART slower than 115200 payload bits/s in 8-N-1?", "Two of each ten transmitted bits are framing, leaving eight payload bits."),
chapter("rtos", "Real-time scheduling, synchronization, and power", "rtos scheduler task priority inversion semaphore mutex real-time sleep brown reset power firmware update", [
  "Real-time correctness includes finishing before a deadline. A task has an execution cost, release condition, and timing requirement. A scheduler chooses runnable work; an interrupt handler handles urgent hardware events. Blocking on an event can let other tasks run, while busy-waiting occupies execution capacity.",
  "Shared data needs synchronization. A mutex protects ownership and may support priority inheritance. A semaphore represents a count or notification and is not interchangeable with every mutex use. Priority inversion occurs when a high-priority task waits on a resource held by lower-priority work, especially when medium-priority tasks delay that holder.",
  "Sleep modes reduce power while selected wake sources remain active. Entry and wake latency must fit deadlines, and clocks or peripheral state may need restoration. Reset, brown-out supervision, watchdog recovery, and firmware update design preserve a known startup path when execution cannot safely continue."
], "Periodic CPU utilization U = Σ(Cᵢ/Tᵢ); U < 1 is necessary on one core but is not a universal schedulability proof", ["Task A takes 1 ms every 5 ms; B takes 2 ms every 10 ms.", "Their utilization is 1/5 + 2/10 = 0.4, or 40% before overhead.", "Check deadlines, blocking, release patterns, and scheduler policy before concluding they are schedulable."], ["Priority inheritance reduces a specific blocking problem; it does not eliminate deadlock.", "A low average utilization can still hide a missed short deadline."], "Why should an ISR avoid an ordinary blocking wait?", "It may execute in a context that cannot sleep and can prevent the task needed to satisfy the wait from running." , ["ostep"]),
chapter("devices", "Reading complete device signal paths", "device sensor signal anatomy failure waveform medical aviation marine defence robotics everyday", [
  "Study a device as a chain of transformations: physical input, sensing, conditioning, conversion, computation, and output or actuation. At each boundary, name the quantity and units. A temperature, voltage, ADC code, and displayed number are related but are not the same signal.",
  "The physical principle determines what a sensor measures directly. Software often estimates the desired quantity indirectly from calibrated measurements. Gain, filtering, sampling, communication, and thresholds affect the result. A block diagram is useful only when its arrows explain what moves and why a downstream block needs it.",
  "A feedback device compares a measurement with a target and adjusts an actuator. Delay, saturation, noisy measurements, and limited actuator authority constrain control. Fault analysis follows the same chain: identify the failed stage, predict the downstream consequence, then distinguish a real environmental change from a measurement or processing fault."
], "Measurement chain: physical quantity → transducer → conditioned signal → samples → estimate → decision/output", ["A temperature sensor generates a voltage proportional to temperature.", "The ADC converts that voltage to a code; calibration converts the code to degrees.", "Changing reference voltage without updating calibration can change the displayed temperature even when the physical temperature is unchanged."], ["A smooth display does not prove the underlying measurement is correct.", "An educational model’s thresholds and transfer functions must not be assumed to be a specific commercial device’s specification."], "Why label arrows with quantities and units?", "It exposes invalid connections and distinguishes raw measurements from derived estimates."),
chapter("mos", "MOS devices and transistor operating regions", "mosfet mos capacitor transistor threshold iv body effect channel semiconductor finfet gaa scaling device", [
  "A MOS transistor uses an insulated gate to control charge in a semiconductor channel. Gate voltage changes the electric field and therefore conduction between source and drain. The threshold is a model parameter marking strong inversion behavior, not an ideal abrupt boundary with absolutely zero current below it.",
  "For a long-channel NMOS, the simple square-law model distinguishes cutoff, linear, and saturation regions using gate overdrive and drain voltage. Saturation in this device model means the drain current is approximately limited by channel conditions; it is not the same as a digital output being high. Body bias and channel-length modulation change the ideal behavior.",
  "Modern short-channel devices require more detailed models, including velocity saturation, leakage, parasitic capacitance, and process variation. FinFET and gate-all-around structures improve electrostatic control. A teaching I–V curve develops intuition but does not replace a foundry model for circuit signoff."
], "Long-channel saturation approximation: ID = ½ μCox(W/L)(VGS−VT)², for VDS ≥ VGS−VT and VGS > VT", ["Let VT=0.4 V and VGS=1.0 V; overdrive is 0.6 V.", "At VDS=0.2 V, the square-law model places the device in the linear region.", "At VDS=0.8 V, it is in saturation. The exact current requires the process and geometry parameters."], ["MOS saturation is not BJT saturation.", "Square-law equations have explicit model and region assumptions."], "How does raising VGS above threshold affect ideal saturation current?", "It raises gate overdrive; the long-channel ideal model makes current proportional to its square."),
chapter("cmos", "CMOS circuits, delay, and power", "cmos inverter nand nor transfer noise margin power dynamic leakage standard cell synthesis logic optimization", [
  "Static CMOS combines a pull-up network of PMOS devices with a complementary pull-down network of NMOS devices. For a stable valid input, the intended output is connected to one rail without a permanent direct path between supplies. The inverter is the basic example: input low enables pull-up; input high enables pull-down.",
  "The voltage transfer curve shows gain and logic thresholds; noise margins describe tolerated disturbance while preserving valid interpretation. During a transition, load capacitance must charge or discharge through finite transistor resistance. Larger devices can drive more current but add capacitance to the previous stage and occupy more area.",
  "Dynamic switching energy grows with capacitance and the square of supply voltage. Short-circuit current occurs during switching when both networks conduct, while leakage contributes even in an idle powered circuit. Synthesis maps logic into a cell library under timing, area, and power constraints; the fewest Boolean literals need not produce the best physical implementation."
], "Dynamic power ≈ α C V² f; first-order delay scales roughly with Rdriver × Cload", ["Hold activity, capacitance, and frequency constant while reducing supply from 1.0 V to 0.8 V.", "The ideal dynamic-power factor becomes 0.8²=0.64, a 36% reduction.", "Actual timing, leakage, and operating limits must also be evaluated; frequency cannot always remain unchanged."], ["Static CMOS still consumes leakage and switching power.", "Increasing drive strength can slow upstream gates through added input capacitance."], "Why does fan-out affect delay?", "More connected inputs generally add capacitive load that the driver must charge and discharge."),
chapter("physical", "Physical design and verification", "layout drc lvs floorplan placement routing clock tree physical gds rtl-to-gds timing closure congestion extraction", [
  "Physical design turns a logical netlist into geometric devices and wires. Floorplanning establishes die or block boundaries, macro positions, power structure, and routing space. Placement assigns cell locations; routing builds connections while respecting the technology’s layers and design rules.",
  "Wires have resistance, capacitance, and coupling. Extracted parasitics therefore change timing and signal integrity relative to an ideal netlist. Clock-tree synthesis distributes capture events with controlled skew and transition quality. Timing closure iteratively changes cells, placement, buffering, and routes while checking all required modes and process corners.",
  "DRC checks geometric manufacturing rules; LVS checks whether extracted connectivity matches the intended schematic or netlist. Neither alone proves logical correctness or timing closure. Signoff combines relevant electrical, timing, physical, power, and verification checks using qualified tools and process data."
], "Approximate wire delay grows with distributed resistance and capacitance; connectivity correctness ≠ timing correctness", ["A routed net matches the schematic, so LVS passes.", "Two metal shapes remain too close under the process spacing rule, so DRC fails.", "Fixing the spacing can alter parasitics, requiring timing to be checked again."], ["A clean DRC report does not prove that the design computes the right function.", "A shortest geometric route may create congestion or poor electrical behavior."], "What does LVS establish?", "That the circuit extracted from layout matches the intended device/connectivity description under the tool’s comparison rules."),
chapter("reliability", "Variation, power integrity, and reliability", "ir drop electromigration variation multi voltage power gating isolation retention thermal reliability", [
  "A chip’s power network has finite resistance and inductance. Current demand can lower the voltage delivered to cells, changing delay and noise margin. Static IR drop reflects sustained resistive loss; transient supply noise also depends on current changes and network dynamics.",
  "Process, supply voltage, and temperature affect device behavior. Analysis across corners and statistical variation prevents a nominal-only result from being mistaken for a robust design. Timing paths can fail setup or hold under different conditions, so the worst case is not the same corner for every check.",
  "Electromigration concerns material movement under current stress. Power gating, isolation, retention, and level shifting introduce sequencing requirements across voltage domains. Thermal management affects leakage, lifetime, and sustained performance. Reliability is a set of coupled electrical and physical constraints rather than one final checkbox."
], "Resistive supply drop: ΔV = I × R; current density J = I/cross-sectional area", ["A local supply path has 0.2 Ω resistance and carries 0.1 A.", "Its resistive drop is 20 mV. At a 0.8 V nominal supply this is 2.5%.", "Timing must use the delivered voltage and relevant dynamic effects, not assume the nominal rail reaches every cell."], ["A nominal timing pass does not establish corner coverage.", "A power-gated domain may require output isolation before its supply is removed."], "Why do power and timing analysis interact?", "Supply droop and temperature change transistor speed, while switching activity determines current and heat."),
chapter("fabrication", "Fabrication, yield, and advanced integration", "fabrication wafer lithography oxidation deposition etch implant yield packaging chiplet interposer process", [
  "Fabrication builds many devices and interconnect layers through repeated material growth or deposition, lithographic patterning, etching, doping, and planarization. A mask describes a pattern for a processing step; the final circuit depends on the complete sequence and its dimensional tolerances.",
  "Yield is the fraction of manufactured units that satisfy the specified tests. Defects, variations, and design sensitivity influence it. Larger die area generally increases exposure to random defects under a simple defect-density model, but real yield analysis also depends on defect clustering, redundancy, and systematic effects.",
  "Packaging supplies electrical connections, mechanical support, power delivery, and heat removal. Chiplets partition a system across multiple die linked by a package interconnect. That can improve reuse and manufacturing economics while introducing link bandwidth, energy, latency, assembly, and test constraints."
], "Simple independent-defect yield model: Y ≈ exp(−D × A), with defect density D and die area A in compatible units", ["Assume D=0.1 defects/cm² and A=2 cm² under the simple model.", "Yield is exp(−0.2)≈0.819, or about 82%.", "This is an illustrative model, not a production forecast without process-specific data."], ["A technology node name is not a complete set of physical dimensions.", "Wafer fabrication and package assembly are different stages."], "Why can splitting a design into chiplets improve yield economics?", "Smaller die can have a higher individual yield and known-good die can be combined, though package and interconnect costs must be included."),
chapter("test", "Design for test, scan, and fault coverage", "dft scan test fault atpg bist mbist lfsr stuck coverage", [
  "Functional verification asks whether a design satisfies its specification. Manufacturing test asks whether fabricated hardware contains faults. Design for test adds observability and controllability so internal state can be exercised and examined efficiently.",
  "Scan chains connect selected storage elements into a shift path in test mode. A pattern is shifted in, the design captures a response, and state is shifted out. Automatic test-pattern generation targets a fault model such as stuck-at or transition faults. Coverage is always relative to that model and the analyzed fault list.",
  "Built-in self-test generates stimuli or checks responses on chip. LFSRs create repeatable pseudorandom patterns; signature analyzers compact responses, introducing a possibility of aliasing. Memory BIST uses structured read/write sequences to expose memory-specific failures. Test logic itself needs mode control, timing analysis, and security consideration."
], "Fault coverage = detected modeled faults / total considered modeled faults", ["A two-input AND output is stuck at zero.", "Applying inputs 1,1 should produce one, so the erroneous zero becomes observable.", "Applying 0,1 would not detect this fault because the correct output is already zero."], ["100% coverage of one fault model is not proof that every physical defect is detectable.", "Scan shifting and functional capture use different operating conditions."], "Why must a test both activate a fault and propagate it?", "The faulty behavior must occur internally and then reach an observable output or scan element to be detected."),
chapter("builder", "Building and validating a complete machine", "builder sandbox custom processor component wire validate probes breakpoint history template", [
  "A constructed processor needs a complete path from instruction fetch to state update. Define component widths, legal drivers, clocked state, instruction fields, and control sequencing before evaluating programs. A connected drawing is not sufficient: each value must arrive at the correct destination at the correct event.",
  "Validation begins with local invariants: compatible widths, driven selects, unique bus ownership, and defined reset state. Then test arithmetic paths, memory reads/writes, branches, and exceptional conditions. Compare a small program’s final state with a hand calculation and inspect intermediate state when it diverges.",
  "Probes record signals over time; breakpoints stop at meaningful conditions; execution history compares successive states. Editor undo changes the design, while execution stepping changes machine state. Keep these distinct so a previous simulation snapshot is not mistaken for a previous circuit definition."
], "Machine transition: (registers, memory, PC)ₜ₊₁ = execute(design, instruction, stateₜ)", ["Build a datapath that adds two registers into a third.", "Load operands 5 and 3, select ADD, enable only the destination, then step once.", "Confirm result 8 and unchanged source registers. Next test zero, maximum values, and overflow."], ["A width mismatch can silently truncate a correct arithmetic result.", "A probe shows what happened; it does not prove the wiring satisfies every input case."], "Why test a branch separately from an ALU operation?", "A correct comparison is insufficient if the PC mux, target calculation, or write control is wrong."),
];
CHAPTERS.push(
chapter("branch", "Branch prediction and speculative recovery", "branch predictor prediction btb bht gshare tournament correlating return stack", [
  "Conditional branches need both a direction decision and a target address. A direction predictor guesses taken or not taken; a branch target buffer caches destinations. A return-address stack exploits the call/return pattern. Predicting a target correctly does not establish that the branch should be taken.",
  "A one-bit predictor remembers the last outcome. A two-bit saturating counter adds hysteresis, so a single unusual outcome need not reverse a strong prediction. Local history describes a particular branch; global history records outcomes across branches. Gshare combines history with address bits, while tournament predictors choose between predictors. Limited tables can alias unrelated branches.",
  "Prediction is evaluated against actual execution. A misprediction redirects fetch and invalidates younger wrong-path work. Recovery cost depends on where the branch resolves and how much state must be repaired. Accuracy, storage, access latency, and energy all matter; one trace is not a universal ranking."
], "Average branch penalty contribution to CPI ≈ branches/instruction × misprediction rate × penalty cycles", ["With 20% branch instructions, 10% mispredictions, and an eight-cycle penalty, the added CPI is 0.2×0.1×8=0.16.", "If the rest of execution costs CPI 1.0 under the model, total CPI becomes 1.16.", "This estimate assumes the penalties do not overlap other stalls."], ["Prediction changes when work begins; it must not change the correct program result.", "A low miss rate can still be costly with a long recovery penalty."], "Why is a two-bit counter useful for a loop branch?", "A single loop exit weakens a strong taken prediction rather than immediately reversing it, so the next loop entry can still be predicted taken."),
chapter("dram", "DRAM banks and memory scheduling", "dram bank rank channel row controller precharge scheduling refresh", [
  "A DRAM access is organized around rows and columns rather than independent ideal words. Activating a row moves its contents into sense amplifiers that also act as a row buffer. Column commands then select data from the open row. Closing or replacing a row requires precharge and timing constraints.",
  "A row hit can reuse the open row. A closed-row access needs activation; a row conflict first replaces a different open row. Banks allow some operations to overlap, while channels provide separate interfaces. Command and data timing constrain which overlaps are actually legal.",
  "A controller schedules requests to balance throughput, latency, and fairness. Prioritizing row hits can reduce average cost but delay other streams. Refresh preserves stored charge and occupies resources. Address mapping across channels, banks, and rows can dramatically alter the behavior of a stride access pattern."
], "Conceptual row-conflict cost = precharge delay + activation delay + column-access delay", ["Requests A and B access different columns in one row: after A activates it, B can be a row hit.", "Request C accesses a different row in the same bank and causes a conflict.", "Mapping C to another independent bank may allow overlap, subject to command and bus constraints."], ["Bank parallelism does not make the shared data bus unlimited.", "DRAM latency is not just CAS latency."], "Why might reordering requests improve bandwidth but hurt fairness?", "Serving many row hits avoids expensive row changes but can postpone requests to other rows."),
chapter("atomics", "Atomic operations, locks, and ordering", "atomic compare-and-swap cas fetch-and-add ll/sc spinlock ticket synchronization", [
  "A plain read followed by a write is not one indivisible operation. Two threads can read the same old counter and both store the same incremented value. Atomic read-modify-write prevents that lost update by making the combined action indivisible relative to competing accesses under the specified memory model.",
  "Compare-and-swap changes a location only if its current value matches an expected value, reporting success or failure. Fetch-and-add increments while returning the old value. Load-linked/store-conditional pairs detect interference according to architecture-specific reservation rules. Algorithms must handle retries and cannot assume unconditional progress.",
  "A spinlock repeatedly checks for ownership and is appropriate only when waiting conditions and execution context permit it. Ticket locks assign an order but still incur cache traffic. Acquire/release semantics order relevant data around ownership transfer. Atomicity of one variable and publication of other variables are distinct guarantees."
], "Lost update: read(x)=0; read(x)=0; write(x)=1; write(x)=1 → final x=1 instead of 2", ["Initialize a counter to zero and let two workers increment it once.", "With separate reads and writes, both may read zero and the final value can be one.", "With two atomic fetch-add operations, each obtains a distinct old value and the final counter is two."], ["Atomic does not mean free of contention or automatically lock-free for every implementation.", "A CAS retry loop needs a correct strategy for changes between attempts, including relevant ABA risks."], "What does a failed compare-and-swap imply?", "The comparison did not match at that atomic operation, so the requested update was not applied." , ["ostep", "riscv"]),
chapter("simd", "SIMD, SMT, and parallel execution styles", "simd vector smt simt flynn sisd misd mimd superscalar lane", [
  "Flynn’s taxonomy classifies instruction and data streams. SIMD applies one instruction to several data elements. MIMD executes multiple instruction streams, as in many multicore systems. Superscalar issue, SIMD width, and number of cores are different sources of parallelism and should not be multiplied without checking the workload.",
  "Vector lanes execute element operations under one instruction. Masking handles inactive elements. GPU-style SIMT presents thread-like work that may execute together in groups; divergent control paths can serialize portions of a group. Neither model eliminates memory bandwidth or data-dependence limits.",
  "SMT lets hardware threads share a core’s execution resources. When one thread cannot use an issue slot, another may fill it. Resources are still finite, and sharing can create contention. Logical thread count is therefore not equivalent to the number of independent full-performance cores."
], "Ideal vector work rate = active lanes × useful lane operations per cycle, subject to throughput and data supply", ["A four-lane vector add computes four independent element sums per instruction.", "If only two lanes are enabled by a mask, only those two results update.", "If memory supplies one element pair per cycle, four arithmetic lanes alone cannot sustain four results per cycle."], ["SMT does not duplicate every execution unit.", "Four-wide issue and four vector lanes describe different mechanisms."], "Why does branch divergence reduce SIMT efficiency?", "Different paths may execute with only a subset of lanes active, reducing useful work per group instruction."),
chapter("multipliers", "Partial products, Booth recoding, and compressor trees", "booth wallace multiplier multiplication partial product compressor array adder", [
  "Binary multiplication builds a shifted copy of the multiplicand for each one in the multiplier. An unsigned n-by-n multiplication needs up to 2n result bits. Array multipliers organize these partial products regularly; tree multipliers reduce them with a different wiring and depth tradeoff.",
  "A 3:2 compressor is a full-adder relationship applied to three bits of the same weight. It produces a sum at that weight and a carry at the next weight without propagating through the full row immediately. Wallace-style reduction repeats compression until two rows remain, then uses a final carry-propagate adder.",
  "Radix-2 Booth multiplication examines a current multiplier bit and a previous bit. Pair 01 adds the multiplicand, 10 subtracts it, and 00 or 11 does neither before an arithmetic shift. Correct sign extension and a sufficiently wide partial result are essential. Booth recoding reduces operations for certain bit patterns; it is not always fewer steps for every implementation."
], "Unsigned product: A×B = Σᵢ bᵢ(A << i); 3:2 compressor preserves weighted sum", ["Compute 5×3 with partial products: 0101×0011.", "The one-bits of 3 produce 00000101 and 00001010.", "Add them to obtain 00001111 = 15. Preserve eight bits for a full four-by-four product."], ["A compressor’s carry has the next higher binary weight.", "Booth arithmetic shifts must preserve the sign of the combined partial state."], "Why is a final carry-propagate adder still needed after a Wallace tree?", "The tree reduces many rows to two; those two rows must still be combined into one conventional binary result."),
chapter("memcells", "SRAM, DRAM, and nonvolatile memory cells", "sram dram cell sense amplifier bitline wordline rom flash eeprom memory vlsi", [
  "An SRAM bitcell stores a state using feedback, commonly a pair of cross-coupled inverters with access transistors. The wordline controls connection to bitlines. Reading must sense the stored state without upsetting it; writing must overpower the previous state under the permitted conditions.",
  "A DRAM cell stores charge on a capacitor accessed by a transistor. Leakage requires periodic refresh. Reading shares small charge with a bitline and a sense amplifier resolves and restores the value. Wordlines, precharge, and sensing therefore participate in a complete operation rather than acting as ideal zero-delay connections.",
  "Nonvolatile cells preserve information without ordinary supply power using a physical storage mechanism such as trapped charge or another persistent state. Program and erase operations differ from reads in latency, voltage requirements, granularity, and endurance. Memory technology choice balances capacity, access time, energy, retention, and manufacturing constraints."
], "Stored capacitor energy: E = ½CV²; read margin and write margin depend on the cell and peripheral circuit", ["An SRAM read starts with prepared bitlines and a selected wordline.", "The stored state causes a small differential; a sense amplifier resolves it.", "A cell that is easy to write but disturbed by the read path is not a robust memory design."], ["SRAM is volatile despite not needing refresh.", "A DRAM read involves sensing and restoration, not simply observing an ideal capacitor."], "Why must DRAM refresh when software is not writing it?", "Leakage changes stored charge, so rows must periodically be sensed and restored."),
chapter("controlsystem", "Feedback, hysteresis, and actuator control", "traffic irrigation street light robot line following motor arm home automation control feedback hysteresis", [
  "A control loop measures an output, compares it with a target, and adjusts an actuator. The plant is the physical process being controlled. Open-loop control acts without measuring the resulting output; closed-loop control uses feedback to correct disturbances and modeling error.",
  "A threshold controller switches at a boundary. With noisy measurements, one threshold can chatter rapidly. Hysteresis uses separate on and off thresholds, preserving state between them. An FSM can add timed transitions, interlocks, and exceptional states rather than embedding all behavior in a sequence of blocking delays.",
  "Actuator saturation, rate limits, sensor delay, and sampling interval constrain response. PID combines proportional error, accumulated error, and rate information; gain choices need a plant model or controlled tuning. A visual simulation is useful for exploring effects, but its simplified plant cannot establish a real system’s stability or safety margins."
], "Error e = setpoint − measurement; hysteresis: turn on below L, turn off above H, with H > L", ["An irrigation controller turns a pump on below 30% moisture and off above 40%.", "At 35%, it retains its previous state rather than switching repeatedly.", "A shared-pump constraint can be modeled as an interlock that prevents conflicting zone commands."], ["A feedback loop can become unstable if gain and delay are ignored.", "Hysteresis adds intentional state; it is not a sensor calibration change."], "Why use separate on and off thresholds?", "They prevent repeated switching when noise or small fluctuations move the measurement near a single boundary."),
chapter("ranging", "Distance measurement and time of flight", "ultrasonic distance sonar radar lidar ranging echo doppler", [
  "Time-of-flight ranging emits a signal, detects its return, and estimates propagation distance from elapsed time. A reflected pulse makes a round trip, so the measured travel distance is twice the one-way range. The propagation speed depends on the medium and signal type.",
  "An ultrasonic sensor uses sound; radar uses electromagnetic waves. Sound speed depends on environmental conditions, so temperature errors can bias ultrasonic distance. Echo thresholds, multipath, target angle, and weak reflections affect detection. A missing echo must produce a timeout or explicit invalid result rather than an invented distance.",
  "Doppler methods estimate radial motion from frequency shift rather than directly from round-trip delay. Range resolution depends on waveform bandwidth or pulse properties and processing, not just the number of display digits. Timing quantization and detection uncertainty should be kept separate from physical range."
], "One-way range d = propagation speed × round-trip time / 2", ["At 343 m/s sound speed, an echo returns after 2 ms.", "Range is 343×0.002/2 = 0.343 m, or 34.3 cm.", "If the actual sound speed differs, the same timing code yields a biased estimate unless compensated."], ["Do not forget the factor of two for a reflected round trip.", "No echo is not the same as a zero-distance object."], "If round-trip time doubles at constant propagation speed, what happens to estimated range?", "The range doubles."),
chapter("signal", "Signal conditioning, filtering, and measurement quality", "ecg eeg emg audio filter noise signal waveform sensor gain microphone imaging camera", [
  "A sensor output often needs amplification, biasing, impedance matching, and filtering before conversion. Gain should place the useful signal inside the converter’s range without clipping large events or offsets. A saturated stage discards information that later digital processing cannot recover.",
  "Filtering attenuates selected frequency components. Low-pass filtering can suppress high-frequency noise; high-pass filtering can remove slow baseline changes. Every real filter also affects phase or timing, and a digital filter adds processing delay. Choose a filter based on signal bandwidth and the measurement’s purpose rather than simply making a plot look smoother.",
  "Noise and artifacts have different origins: electrical interference, motion, quantization, sensor limitations, and environmental changes. Averaging uncorrelated noise can improve a stable estimate but blurs rapidly changing signals. A derived value needs a documented algorithm and calibration; a visually plausible waveform alone is not validation."
], "For independent zero-mean noise, averaging N samples reduces standard deviation approximately by √N", ["Average 16 independent noisy readings of a stable quantity.", "The ideal random-noise standard deviation falls by a factor of four.", "A constant calibration bias remains unchanged, and the averaging interval delays response to a real step."], ["Filtering cannot recover clipped data.", "Averaging reduces random variation, not an unknown systematic offset."], "Why can smoothing make a monitor react more slowly?", "It combines present samples with older data, spreading a rapid change over time."),
);
